/* SOURCE: src/storage.js */
function validState(raw){
 window.ApelexEpoch?.prepare(raw,REWARDS);
 window.ApelexGame?.prepare(raw);
 if(!raw||raw.version!==1||!Array.isArray(raw.earned)||!Array.isArray(raw.activity))throw Error('Formato inválido');
 const s=fresh();
 if(Array.isArray(raw.crmLog))s.crmLog=raw.crmLog.slice(-50).filter(x=>x!==undefined&&JSON.stringify(x).length<4000).map(x=>JSON.parse(JSON.stringify(x)));while(JSON.stringify(s.crmLog).length>40000)s.crmLog.shift();
 for(const c of COURSES){
  const p=raw.projects?.[c.id];if(p&&typeof p.text==='string')s.projects[c.id]={text:p.text.slice(0,20000),checks:[0,1,2,3].map(i=>p.checks?.[i]===true),reviewed:p.reviewed===true};
  const a=raw.exams?.[c.id];if(a&&Number.isFinite(a.last)&&Number.isFinite(a.best)&&Array.isArray(a.answers)&&a.answers.length===4&&a.answers.every(v=>Number.isInteger(v)&&v>=0&&v<3))s.exams[c.id]={last:Math.max(0,Math.min(100,a.last)),best:Math.max(0,Math.min(100,a.best)),attempts:Number.isInteger(a.attempts)?Math.max(1,Math.min(100000,a.attempts)):1,answers:a.answers};
  if(typeof raw.courseDates?.[c.id]==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(raw.courseDates[c.id]))s.courseDates[c.id]=raw.courseDates[c.id];
 }
 if(raw.study&&typeof raw.study==='object'){s.study.level=['Todos','Principiante','Intermedio','Aplicación avanzada'].includes(raw.study.level)?raw.study.level:'Todos';s.study.query=typeof raw.study.query==='string'?raw.study.query.slice(0,100):'';}

 if(raw.notes&&typeof raw.notes==='object')for(const m of LESSONS)if(typeof raw.notes[m.id]==='string')s.notes[m.id]=raw.notes[m.id].slice(0,12000);
 if(Array.isArray(raw.mistakes))s.mistakes=[...new Set(raw.mistakes.filter(k=>typeof k==='string'&&!!questionFor(k)))];
 s.name=typeof raw.name==='string'?raw.name.slice(0,80):'';
 s.earned=[...new Set(raw.earned.filter(k=>Object.hasOwn(REWARDS,k)))];
 s.activity=[...new Set(raw.activity.filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))].sort();
 s.lastView=['city','dashboard','catalog','progress','certificate','review','labs','plan','sources',...COURSES.flatMap(c=>[c.id,'exam-'+c.id,'cert-'+c.id]),...MODULES.map(m=>m.id)].includes(raw.lastView)?raw.lastView:'dashboard';
 if(raw.ticketDrafts&&typeof raw.ticketDrafts==='object')for(const t of TICKETS){const d=raw.ticketDrafts[t.id];if(d&&['P1','P2','P3','P4'].includes(d.priority)&&Number.isInteger(d.solution)&&d.solution>=0&&d.solution<3)s.ticketDrafts[t.id]={priority:d.priority,solution:d.solution};}
 if(raw.flow&&typeof raw.flow==='object'){for(const k of ['trigger','filter','action'])s.flow[k]=typeof raw.flow[k]==='string'?raw.flow[k].slice(0,50):'';s.flow.dedupe=raw.flow.dedupe===true;s.flow.retry=raw.flow.retry===true;}
 s.prompt=typeof raw.prompt==='string'?raw.prompt.slice(0,5000):'';
 if(raw.cert&&typeof raw.cert.name==='string'&&typeof raw.cert.date==='string'&&typeof raw.cert.id==='string'&&COURSES.every(c=>courseComplete(c,s)))s.cert={name:raw.cert.name.slice(0,80),date:raw.cert.date.slice(0,40),id:raw.cert.id.slice(0,80)};
 return s;
}


