function terminal(){return heading('LAB / SOPORTE IT','La red tiene algo que decir.','Ejecutá los cuatro comandos objetivo. Las respuestas son simuladas: no se hacen conexiones reales.')+`<div class="split"><div><div class="terminal"><div class="terminal-bar"><i></i><i></i><i></i><span>cmd.exe · TECHSKILL-LAB</span></div><pre id="console" class="console" role="log" aria-live="polite" aria-label="Salida de terminal">TechSkill OS [Simulación educativa v1.0]
Escribí help para ver comandos y ejemplos.
Objetivo: identificar IP, conectividad, ruta y resolución DNS.
</pre><form id="terminalForm" autocomplete="off"><span>C:\\Lab&gt;</span><label for="command" class="hidden">Comando</label><input id="command" maxlength="160" placeholder="ping 8.8.8.8" spellcheck="false" autocapitalize="off"><button type="submit">Ejecutar ↵</button></form></div><p class="muted small" style="margin-top:12px">↑ / ↓ Historial · help Ayuda · cls Limpiar · Las repeticiones no suman XP.</p></div><aside class="panel"><div class="eyebrow">CHECKLIST / 40 XP CADA UNO</div><h3>Diagnóstico de conectividad</h3><ul class="tasklist">${[['ipconfig','Ver tu configuración','ipconfig'],['ping','Comprobar alcance IP','ping 8.8.8.8'],['tracert','Seguir la ruta','tracert google.com'],['nslookup','Consultar DNS','nslookup google.com']].map(([k,t,c])=>`<li><span class="check">${has('terminal:'+k)?'✓':'○'}</span>${t}<br><code>${c}</code></li>`).join('')}</ul><p class="muted small">Un ping exitoso demuestra respuesta ICMP en este escenario; no garantiza que todos los servicios funcionen.</p></aside></div>`;}

function commandResponse(input){const parts=input.trim().toLowerCase().split(/\s+/),cmd=parts[0],args=parts.slice(1);const target=args[0];
 if(cmd==='help')return {text:'Comandos disponibles:\n  ipconfig [ /all ]  Configuración IP\n  ping 8.8.8.8      Prueba de conectividad\n  tracert google.com Ruta de red\n  nslookup [dominio] Consulta DNS (sin dominio: sesión de ayuda)\n  cls / clear       Limpiar pantalla\nLos objetivos con XP usan exactamente los destinos indicados.'};
 if(cmd==='cls'||cmd==='clear')return {clear:true};
 if(cmd==='ipconfig'&&(args.length===0||(args.length===1&&target==='/all')))return {key:'ipconfig',text:'Configuración IP de Windows\n\nAdaptador Ethernet LAB:\n   Dirección IPv4 . . . . . : 192.168.1.42\n   Máscara de subred . . . : 255.255.255.0\n   Puerta de enlace . . . : 192.168.1.1\n   DHCP habilitado . . . : Sí\n   Servidor DNS . . . . . : 8.8.8.8\n\nLectura: equipo en la red 192.168.1.0/24.'};
 if(cmd==='ping'&&target==='8.8.8.8'&&args.length===1)return {key:'ping',text:'Haciendo ping a 8.8.8.8 con 32 bytes de datos:\nRespuesta desde 8.8.8.8: bytes=32 tiempo=18ms TTL=117\nRespuesta desde 8.8.8.8: bytes=32 tiempo=21ms TTL=117\nRespuesta desde 8.8.8.8: bytes=32 tiempo=19ms TTL=117\nRespuesta desde 8.8.8.8: bytes=32 tiempo=20ms TTL=117\n\nPaquetes: enviados = 4, recibidos = 4, perdidos = 0 (0%).\nMínimo = 18ms, máximo = 21ms, media = 19ms.\nDiagnóstico: hay alcance IP al destino simulado.'};
 if(cmd==='tracert'&&target==='google.com'&&args.length===1)return {key:'tracert',text:'Traza a google.com [142.250.78.14], máximo 30 saltos:\n  1     1 ms     1 ms     2 ms  192.168.1.1\n  2     7 ms     8 ms     7 ms  100.64.0.1\n  3    16 ms    17 ms    16 ms  203.0.113.10\n  4    23 ms    22 ms    23 ms  142.250.78.14\nTraza completa. Ruta y direcciones ilustrativas.'};
 if(cmd==='nslookup'&&!args.length)return {text:'Servidor predeterminado: dns.google\nAddress: 8.8.8.8\nEn este laboratorio usá: nslookup google.com\n(Sesión interactiva de nslookup no implementada).'};
 if(cmd==='nslookup'&&target==='google.com'&&args.length===1)return {key:'nslookup',text:'Servidor: dns.google\nAddress: 8.8.8.8\n\nRespuesta no autoritativa:\nNombre: google.com\nAddress: 142.250.78.14\n\nLectura: el DNS resolvió el nombre a una dirección IPv4.'};
 if(['ping','tracert','nslookup','ipconfig'].includes(cmd))return {text:'Sintaxis o destino fuera del escenario. Consultá help.\nEjemplos: ping 8.8.8.8 · ipconfig · tracert google.com · nslookup google.com'};
 return {text:'"'+input+'" no se reconoce como un comando de este laboratorio. Escribí help.'};
}

function tickets(){const t=TICKETS[ticketIndex],solved=has('tickets:'+t.id),d=state.ticketDrafts[t.id];return heading('LAB / HELPDESK L1–L2','Cada ticket necesita criterio.','Elegí la prioridad y el siguiente paso técnico. Podés corregir y volver a intentar.')+`<div class="split" style="grid-template-columns:minmax(220px,.8fr) minmax(0,1.5fr)"><aside><div class="eyebrow">BANDEJA / ${count('tickets')} DE 3 RESUELTOS</div>${TICKETS.map((t,i)=>`<button class="ticket-item ${i===ticketIndex?'selected':''}" data-ticket="${i}"><small>${t.code} ${has('tickets:'+t.id)?'· ✓ Resuelto':'· Abierto'}</small><strong>${t.title}</strong></button>`).join('')}<div class="panel small muted"><b style="color:var(--text)">Matriz del laboratorio</b><br>P1: operación crítica detenida, impacto amplio.<br>P2: impacto alto, urgencia alta, alcance acotado.<br>P3: impacto individual, existe alternativa.<br>P4: consulta o solicitud sin urgencia.<br><br>En una empresa real se usa su matriz y SLA.</div></aside><section class="panel"><div class="section-head"><span class="tag">${t.code}</span><span class="badge ${solved?'':'locked'}">${solved?'✓ Resuelto':'Pendiente'}</span></div><h2>${t.title}</h2><p class="muted small">${t.from}</p><p>${t.body}</p><form id="ticketForm"><label for="priority">1. Asigná la prioridad</label><select id="priority" required ${solved?'disabled':''}><option value="">Seleccionar prioridad…</option>${['P1','P2','P3','P4'].map(p=>`<option ${d?.priority===p?'selected':''}>${p}</option>`).join('')}</select><label>2. Elegí el siguiente paso</label><div class="options">${t.options.map((o,i)=>`<label class="option checkbox" style="margin:0"><input type="radio" name="solution" value="${i}" required ${d?.solution===i?'checked':''} ${solved?'disabled':''}><span>${o}</span></label>`).join('')}</div><button class="primary" ${solved?'disabled':''}>Resolver ticket · 60 XP</button></form><div id="ticketFeedback">${solved?`<div class="feedback">✓ ${t.why}</div>`:''}</div></section></div>`;}

function crm(){const qualified=BANT.every(b=>has('crm:'+b.key)),closed=has('crm:meeting');return heading('LAB / CRM & VENTAS B2B','Preguntá mejor. Calificá mejor.','Usá BANT para conocer el contexto del prospecto antes de proponer una reunión.')+`<div class="split"><section class="panel"><div class="section-head"><h3 style="margin:0">Nueva oportunidad · Nexo Retail</h3><span class="badge">SDR / Discovery</span></div><div class="chat"><div class="bubble"><b>Paula · Coordinadora de operaciones</b><br>Hola, estamos buscando una solución para ordenar ventas y soporte. ¿Podrías contarme cómo nos ayudarían?</div>${BANT.filter(b=>has('crm:'+b.key)).map(b=>`<div class="bubble you">${b.q}</div><div class="bubble"><b>Paula</b><br>${b.a}</div>`).join('')}${closed?'<div class="bubble you">¿Agendamos una demo de 25 minutos esta semana con vos y la directora para validar el flujo de pedidos y el encaje con el presupuesto?</div><div class="bubble">Sí, enviame dos horarios para coordinar con la directora. ¡Gracias!</div>':''}</div><h3>Tu próximo movimiento</h3><div class="options">${BANT.filter(b=>!has('crm:'+b.key)).map(b=>`<button class="option" data-bant="${b.key}">${b.q}</button>`).join('')}${closed?'':`<button class="option" data-crm="pitch">Ofrecer 30% de descuento y pedir la compra inmediata.</button><button class="primary" id="meeting">Proponer demo con quienes deciden · 60 XP</button>`}</div><div id="crmFeedback">${closed?'<div class="feedback">✓ Reunión acordada en la simulación. No se envió ninguna invitación real.</div>':''}</div></section><aside class="panel"><div class="eyebrow">FICHA DEL PROSPECTO</div><h3>BANT · ${BANT.filter(b=>has('crm:'+b.key)).length}/4</h3><ul class="tasklist">${BANT.map(b=>`<li><span class="check">${has('crm:'+b.key)?'✓':'○'}</span><b>${b.label}</b><p class="muted small" style="margin:6px 0 0">${has('crm:'+b.key)?b.a:'Todavía sin calificar'}</p></li>`).join('')}</ul><p class="muted small">${qualified?'Buen encaje: hay necesidad, presupuesto, acceso a la decisora y plazo definido. Proponé un siguiente paso concreto.':'Escuchá primero. Las cuatro dimensiones ayudan a evaluar si una reunión tiene sentido.'}</p></aside></div>`;}

function flowSelect(id,title,options){return `<div class="flow-node"><b>${title}</b><label class="hidden" for="${id}">${title}</label><select id="${id}" data-flow="${id}" required><option value="">Seleccioná una opción…</option>${options.map(([v,t])=>`<option value="${v}" ${state.flow[id]===v?'selected':''}>${t}</option>`).join('')}</select></div>`;}

function evaluatePrompt(text){const W=window.ApelexWritten,s=norm(text),has=pattern=>!!W.evidence(text,pattern);const rules=[
 ['Rol',has('(?:actua|sos|eres|asumi|rol|especialista|analista|experto)'),'Defini un rol relevante.'],
 ['Tarea',has('(?:clasific|prioriz|analiz|resum|asign).{0,65}(?:ticket|incidente|caso)'),'Pedi una accion concreta sobre los tickets.'],
 ['Contexto',has('(?:ticket|incidente|soporte).{0,85}(?:impacto|urgencia|sla|prioridad|usuario)'),'Explica con que contexto se decide la prioridad.'],
 ['Formato',has('(?:entreg|devuelv|formato|salida|json|tabla).{0,80}(?:json|tabla|columnas|lista|campos|prioridad|motivo)'),'Defini una salida y sus campos.'],
 ['Privacidad',has('(?:no (?:incluy|revel|invent|expong|compart)|sin datos personales|anonimiz|oculta|protege).{0,65}(?:dato|persona|secreto|informacion|token|contrasena)|sin datos personales'),'Indica que se protegen los datos y secretos.'],
 ['Criterios',has('(?:si |cuando |criterio|ejemplo|p1|p2).{0,85}(?:falta|impacto|urgencia|revision|prioridad|dato|p1|p2|afect)'),'Inclui una regla de decision o que hacer si faltan datos.']
 ];const enough=!!s.trim(),score=Math.round(rules.filter(r=>r[1]).length/6*100),unsafe=W.review('security',text).errors.length>0;return {rules,score,enough,pass:!unsafe&&score>=80&&rules[1][1]&&rules[2][1]&&rules[4][1]};}


