function selectChampion(id){if(champion())return false;const hero=heroes.find(h=>h.id===id);if(!hero)return false;fact('v15:avatar:'+ApelexEpoch.epoch(state)+':'+id);selectedTab=id;render();chrome();return true;}

const reconciledAvatars=new Set();
