const kinds={search:'Sopa de letras',cross:'Crucigrama',riddle:'Acertijo',match:'Unir conceptos',order:'Ordenar pasos',fill:'Completar',error:'Encontrar el error'},runs=new Map();
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'');
