const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(pos,3));geometry.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geometry.setIndex(indices);geometry.computeVertexNormals();const cloth=mesh(parent,geometry,color);cloth.name=name;cloth.material=mat(color,0,.84);cloth.material.side=T.DoubleSide;cloth.userData.attachment=cape?'collar':'waist';cloth.userData.topY=topY;
const trim=role==='SUPPORT'?0xdfc4a3:cfg.accent;for(const u of closed?[0,.25,.5,.75,1]:[0,1]){const pts=[];for(let j=0;j<=12;j++)pts.push(point(u,j/12,false));seam(parent,trim,pts,.006);}
