seam(bodyform,gold,[[0,1.65,.272],[0,1.3,.278],[0,.9,.238]],.006);for(let i=0;i<14;i++)box(bodyform,0xc9b788,(i%2?1:-1)*.007,.95+i*.044,.275,.012,.012,.009);ring(bodyform,gold,.025,1.1,.293,.021,.006);
