function display(){if(!battle||!$('duelPlay'))return;const b=battle,h=ApelexGame.champion(),bad=ApelexGame.heroes.find(h=>h.id===b.enemy);$('duelPlay').innerHTML=`<div class="duel-hud"><label>${esc(h.nombre)} <strong id="heroHP">${b.hp}</strong>/100<progress id="heroHealth" max="100" value="${b.hp}"></progress></label><label>Eco de ${esc(bad.nombre)} <strong id="enemyHP">${b.enemyHP}</strong>/100<progress id="enemyHealth" max="100" value="${b.enemyHP}"></progress></label></div><div class="duel-scene" id="duelScene" data-event="idle"></div><div id="duelResult" role="status"></div><div class="duel-question"><div class="duel-time"><span>Tiempo restante: <b id="duelTime">${b.seconds}</b> s</span><progress id="duelClock" max="${b.seconds}" value="${b.seconds}"></progress></div><div id="duelQuestion"></div><div id="duelFeedback" role="status"></div></div>`;scene();question();}
function question(){if(!battle||battle.done)return;const b=battle,q=b.questions[b.index%b.questions.length];b.locked=false;b.actor=null;b.deadline=Date.now()+b.seconds*1000;b.remaining=b.seconds*1000;$('duelQuestion').innerHTML=`<span class="small">${esc(LESSONS.find(l=>l.id===q.lesson).title)} · Turno ${b.index+1}</span><h3>${esc(q.q)}</h3><div class="options">${q.o.map((o,i)=>`<button data-duel-answer="${i}">${esc(o)}</button>`).join('')}</div>`;$('duelFeedback').innerHTML='';$('duelScene').dataset.event='idle';tick();}
function tick(){if(!battle||battle.locked||battle.done||battle.paused||document.hidden)return;const remaining=battle.deadline-Date.now();const time=$('duelTime'),bar=$('duelClock');if(time)time.textContent=Math.max(0,Math.ceil(remaining/1000));if(bar)bar.value=Math.max(0,remaining/1000);if(remaining<=0)answer(null);}
function answer(n){const b=battle;if(!b||b.done||b.locked||b.scope!==scope()||b.paused||document.hidden)return;if(Date.now()>=b.deadline)n=null;const q=b.questions[b.index%b.questions.length],ok=n!==null&&n===q.a;b.locked=true;b.actor=ok?'hero':'enemy';b.animStarted=performance.now();if(ok)b.enemyHP=Math.max(0,b.enemyHP-25);else b.hp=Math.max(0,b.hp-(ApelexGame.champion().id==='TOP'?20:34));for(const [id,v]of [['heroHP',b.hp],['enemyHP',b.enemyHP]])$(id).textContent=v;$('heroHealth').value=b.hp;$('enemyHealth').value=b.enemyHP;$('duelScene').dataset.event=ok?'hero-attack':'enemy-attack';$('duelQuestion').querySelectorAll('button').forEach(x=>x.disabled=true);$('duelFeedback').innerHTML=`<p><strong>${ok?'✓ ¡Correcto! Tu ataque causa 25 de daño.':n===null?'Se terminó el tiempo. El rival ataca.':'Respuesta incorrecta. El rival ataca.'}</strong></p><p>${esc(q.why)}</p><p>Respuesta: ${esc(q.o[q.a])}</p>`;if(!ok)rememberMistake(q.key);
if(b.enemyHP===0||b.hp===0){b.done=true;b.win=b.enemyHP===0;clearInterval(timer);timer=null;const rewardKey='v9:drill:'+ApelexGame.topic(q.key)+':'+dateKey(),gain='v15:gain:'+ApelexEpoch.epoch(state)+':base:'+rewardKey,already=has(rewardKey)||has(gain);if(b.win){ApelexGame.fact(rewardKey,60);practice();chrome();}save();$('duelResult').innerHTML=`<h3>${b.win?'¡Victoria! Eco restaurado':'Derrota · tu progreso está a salvo'}</h3><p>${b.win?(already?'Ya recibiste la recompensa de este distrito hoy. Podés seguir practicando sin duplicar XP.':'+60 XP · recompensa de práctica de este distrito, una vez por día.'):'Repasá la explicación y volvé a intentarlo. No se resta XP.'}</p><button data-duel-replay>Volver a combatir</button>`;$('duelScene').classList.add(b.win?'duel-victory':'duel-defeat');$('duelClock').value=0;$('duelPlay').querySelector('.duel-time').hidden=true;}
else $('duelFeedback').insertAdjacentHTML('beforeend','<button data-duel-next class="primary">Siguiente turno →</button>');}
function start(){stop();const h=ApelexGame.champion();if(!h)return;choice=$('duelCourse').value;enemy=$('duelEnemy').value;seconds=Number($('duelSeconds').value);battle={id:++serial,scope:scope(),course:choice,enemy,seconds,questions:shuffled(pool(choice)),index:0,hp:100,enemyHP:100,locked:false,done:false,paused:false};display();timer=setInterval(tick,150);$('duelPlay').scrollIntoView({block:'start',behavior:reduced()?'instant':'smooth'});}
function mount(){const m=LESSONS.find(l=>l.id===view);if(m){lastLesson=m.id;const c=courseFor(m.id);if(c)choice=c.id;if(window.modoEnsenanza==='ludico'&&!$('lessonDuel')){const box=document.createElement('section');box.className='panel';box.id='lessonDuel';box.innerHTML='<h2>Defendé este distrito</h2><p>Practicá los temas de este curso en un combate a contrarreloj.</p><button data-lesson-duel>Ir al combate</button>';$('app').append(box);}}
if(battle&&(!['labs','city'].includes(view)||battle.scope!==scope()||window.modoEnsenanza!=='ludico'))stop();if(window.modoEnsenanza!=='ludico')return;const old=$('startBoss')?.closest('section');if(old){if(battle)stop();old.outerHTML=html();}}
