function pause(){if(renderer)renderer.paused=true;if(!battle||battle.paused)return;battle.remaining=Math.max(0,battle.deadline-Date.now());battle.paused=true;if($('duelPause'))return;const p=document.createElement('p');p.id='duelPause';p.setAttribute('role','status');p.textContent='Combate en pausa. El tiempo se conserva al volver a la app.';$('duelPlay')?.prepend(p);}
